"use client";
import React from "react";
import { motion } from "framer-motion";

const DisplayCards = ({ cards = [] }) => {
  return (
    <div className="relative w-full max-w-5xl mx-auto px-4">
      {/* Increased height container to show stacked cards */}
      <div className="relative flex items-start justify-center" style={{ minHeight: "520px", paddingTop: "60px" }}>
        {cards.map((card, index) => {
          const offsets = [
            { x: 0, y: 0, zIndex: 3, hoverY: -50 },
            { x: 140, y: 50, zIndex: 2, hoverY: 0 },
            { x: 280, y: 100, zIndex: 1, hoverY: 50 },
          ];
          const offset = offsets[index];

          return (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 100 }}
              whileInView={{ opacity: 1, y: offset.y }}
              viewport={{ once: true }}
              transition={{ duration: 0.7, delay: index * 0.2, ease: [0.25, 0.46, 0.45, 0.94] }}
              whileHover={{ y: offset.hoverY, transition: { duration: 0.5, ease: "easeOut" } }}
              className="absolute w-full max-w-sm cursor-pointer"
              style={{
                zIndex: offset.zIndex,
                left: "50%",
                marginLeft: `${-192 + offset.x}px`,
              }}
            >
              {/* Card Container */}
              <div
                className="relative rounded-2xl overflow-hidden"
                style={{
                  background: "linear-gradient(145deg, #1a1510 0%, #0f0a08 100%)",
                  border: "1px solid rgba(212, 175, 55, 0.3)",
                  boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.6)",
                }}
              >
                {/* Top accent bar */}
                <div
                  className="absolute top-0 left-0 right-0 h-1"
                  style={{ background: "linear-gradient(90deg, #d4af37, #f4d77a, #d4af37)" }}
                />

                {/* Card Content */}
                <div className="relative z-10 p-6">
                  {/* Icon */}
                  <div
                    className="w-10 h-10 rounded-lg flex items-center justify-center mb-4"
                    style={{
                      background: "rgba(212, 175, 55, 0.15)",
                      color: "#d4af37",
                    }}
                  >
                    {card.icon}
                  </div>

                  {/* Badge */}
                  <div className="mb-3">
                    <span
                      className="inline-block text-xs font-semibold uppercase tracking-wider px-2 py-1 rounded-md"
                      style={{
                        background: "rgba(212, 175, 55, 0.15)",
                        color: "#d4af37",
                      }}
                    >
                      {card.badge}
                    </span>
                  </div>

                  {/* Title */}
                  <h3 className="text-xl font-semibold text-white mb-2" style={{ fontFamily: "Cormorant Garamond, serif" }}>
                    {card.title}
                  </h3>

                  {/* Description */}
                  <p className="text-sm leading-relaxed mb-4" style={{ color: "rgba(255,255,255,0.6)" }}>
                    {card.description}
                  </p>

                  {/* Date */}
                  <p className="text-xs" style={{ color: "rgba(255,255,255,0.4)" }}>
                    {card.date}
                  </p>
                </div>

                {/* Bottom decorative corner */}
                <div
                  className="absolute bottom-0 right-0 w-20 h-20"
                  style={{
                    borderBottom: "2px solid #d4af37",
                    borderRight: "2px solid #d4af37",
                    opacity: 0.2,
                  }}
                />
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

export default DisplayCards;
